import enum
from datetime import datetime

from sqlalchemy import (
    Column,
    DateTime,
    Enum,
    ForeignKey,
    Integer,
    String,
    UniqueConstraint,
)
from sqlalchemy.dialects.postgresql import JSON, UUID
from src.db.session import Base


class SessionStatus(str, enum.Enum):
    created = "created"
    in_progress = "in_progress"
    submitted = "submitted"
    expired = "expired"


class QuizSession(Base):
    __tablename__ = "quiz_sessions"

    id = Column(Integer, primary_key=True, index=True)
    # session_id is generated by the service layer (single source of truth);
    # nullable=False makes a missing value fail loudly at insert.
    session_id = Column(UUID(as_uuid=True), unique=True, nullable=False)
    test_id = Column(Integer, ForeignKey("tests.id", ondelete="CASCADE"), nullable=False)
    submission_id = Column(
        Integer,
        ForeignKey("test_submissions.id", ondelete="SET NULL"),
        nullable=True,
    )
    user_id = Column(Integer, nullable=False)
    session_token = Column(String(64), unique=True, nullable=False)
    status = Column(Enum(SessionStatus), nullable=False, default=SessionStatus.in_progress)
    current_index = Column(Integer, nullable=False, default=0)
    server_started_at = Column(DateTime(timezone=True), nullable=False)
    expires_at = Column(DateTime(timezone=True), nullable=False)
    submitted_at = Column(DateTime(timezone=True), nullable=True)
    created_at = Column(DateTime(timezone=True), nullable=False, default=datetime.utcnow)
    updated_at = Column(
        DateTime(timezone=True),
        nullable=False,
        default=datetime.utcnow,
        onupdate=datetime.utcnow,
    )


class QuizSessionQuestion(Base):
    __tablename__ = "quiz_session_questions"

    id = Column(Integer, primary_key=True, index=True)
    quiz_session_id = Column(
        Integer,
        ForeignKey("quiz_sessions.id", ondelete="CASCADE"),
        nullable=False,
    )
    question_id = Column(String(64), nullable=False)
    question_index = Column(Integer, nullable=False)
    question_type = Column(String(32), nullable=False)
    snapshot_json = Column(JSON, nullable=False)

    __table_args__ = (
        UniqueConstraint("quiz_session_id", "question_index", name="uq_session_question_index"),
    )
